import './App.css';
import { useState } from 'react';
import Header from './components/Header';
import Calendar from './components/Calendar';
import Table from './components/Table';
import Results from './components/Results';

function App() {
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: 'selection'
    }
  ]);

  const [shifts, setShifts] = useState([]);

  const [tips, setTips] = useState([
    {
      date: new Date(),
      morningTip: 0,
      eveningTip: 0,
    }
  ]);

  function handleRange(item) {
    setRange([item.selection]);
  };

  function handleShifts(date, name, morningOrEvening, hours) {
    // const isFound = shifts.find((shift) => { shift.date === date && shift.name === name });
    // const isFound = true;

    // if (isFound) {
    //   setShifts((prevShifts) => {
    //     switch (morningOrEvening) {
    //       case "morningHours":
    //         return {
    //           ...prevShifts,
    //           morningHours: +hours,
    //         };
    //       case "eveningHours":
    //         return {
    //           ...prevShifts,
    //           eveningHours: +hours,
    //         }
    //       default:
    //         break;
    //     }
    //   });
    // }

    setShifts((prevShifts) => {
      const existingShiftIndex = prevShifts.findIndex(
        (shift) => shift.date === date && shift.name === name);

        if (existingShiftIndex !== -1) {
          return prevShifts.map((shift, index) => {
            if(index === existingShiftIndex) {
              return {
                ...shift,
                [morningOrEvening]: +hours,
              }
            }
          })
        }
      let newShift = {};

      switch (morningOrEvening) {
        case "morningHours":
          newShift = {
            date: date,
            name: name,
            morningHours: +hours,
            eveningHours: 0,
          }
          break;
        case "eveningHours":
          newShift = {
            date: date,
            name: name,
            morningHours: 0,
            eveningHours: +hours,
          }
          break;
        default:
          break;
      }

      return [...prevShifts, newShift];
    });
  };

  console.log(shifts)

  return (
    <div className="App">
      <Header />
      <div className='wrapper'>
        <Calendar range={range} onRangeClick={handleRange} />
        <Table range={range} shifts={shifts} onShiftsChange={handleShifts} />
        <Results />
      </div>
    </div>
  );
}

export default App;
